content.problemStatement:
The power of a number indicates how many times that number is multiplied by itself.
You are given a function,
int CheckPowerOfTwo(int n);
int CheckPowerOfTwo(int n);
static int CheckPowerOfTwo(int n);
static int CheckPowerOfTwo(int n);
def CheckPowerOfTwo(n):
function CheckPowerOfTwo(n){}
function CheckPowerOfTwo(n){}
The function accepts an integer 'n' as its argument. Implement the function to determine if it is a
power of 2. If 'n' is a power of 2, then return the power, else return -1.
Assumption: n > 0

code.C:
#include <stdio.h>
int main() {
    long long n; if (scanf("%lld", &n) != 1) return 0;
    if (n > 0 && (n & (n - 1)) == 0) {
        int k = 0;
        while ((1LL << k) < n) k++;
        printf("%d\n", k);
    } else puts("-1");
    return 0;
}

code.C++:
#include <iostream>
using namespace std;
int main() {
    long long n; if (cin >> n) {
        if (n > 0 && (n & (n - 1)) == 0) {
            int k = 0;
            while ((1ULL << k) < (unsigned long long)n) k++;
            cout << k << "\n";
        } else cout << "-1\n";
    }
    return 0;
}

