import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            long n = sc.nextLong();
            if (n > 0 && (n & (n - 1)) == 0) {
                int k = 0;
                while ((1L << k) < n) k++;
                System.out.println(k);
            } else System.out.println("-1");
        }
    }
}

